/* Calculateur de Bayes : décomposition des alertes en vraies/fausses */
(function () {
  var svg = document.getElementById("by-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  function draw(){
    var prior=v("by-prior")/100, sens=v("by-sens")/100, fpr=v("by-fpr")/100;
    setT("by-prior-o",(prior*100).toFixed(1)+"%"); setT("by-sens-o",(sens*100).toFixed(0)+"%"); setT("by-fpr-o",(fpr*100).toFixed(1)+"%");
    var tp = prior*sens;                 // vrais positifs
    var fp = (1-prior)*fpr;              // faux positifs
    var pplus = tp+fp;                   // Pr(alerte)
    var post = pplus>0 ? tp/pplus : 0;
    setT("by-post",(post*100).toFixed(1)+"%");
    setT("by-fshare", pplus>0 ? ((fp/pplus)*100).toFixed(1)+"%" : "—");

    var W=520,H=200,L=12,R=12,T=24,B=28, pw=W-L-R;
    var g="";
    // Rangée 1 : population (danger vs sain)
    var y1=T, h=34;
    var wD = Math.max(prior*pw, 0);
    g+='<text class="lab" x="'+L+'" y="'+(y1-6)+'">'+(al()==="en"?"Population":(al()==="nl"?"Populatie":"Population"))+'</text>';
    g+='<rect x="'+L+'" y="'+y1+'" width="'+wD.toFixed(1)+'" height="'+h+'" fill="var(--crimson)"/>';
    g+='<rect x="'+(L+wD).toFixed(1)+'" y="'+y1+'" width="'+(pw-wD).toFixed(1)+'" height="'+h+'" fill="var(--surface)" stroke="var(--border)"/>';
    if (wD>34) g+='<text class="val" x="'+(L+4)+'" y="'+(y1+h/2+4)+'">'+(prior*100).toFixed(1)+'%</text>';
    g+='<text class="ax" x="'+(L+wD+4).toFixed(1)+'" y="'+(y1+h/2+4)+'" fill="var(--ink-mute)">'+(al()==="en"?"healthy":(al()==="nl"?"gezond":"sains"))+'</text>';

    // Rangée 2 : alertes (vraies vs fausses), rescalées pour remplir la largeur
    var y2=T+h+40;
    var wTP = pplus>0 ? (tp/pplus)*pw : 0;
    g+='<text class="lab" x="'+L+'" y="'+(y2-6)+'">'+(al()==="en"?"Alarms":(al()==="nl"?"Alarmen":"Alertes"))+' (Pr='+(pplus*100).toFixed(1)+'%)</text>';
    g+='<rect x="'+L+'" y="'+y2+'" width="'+wTP.toFixed(1)+'" height="'+h+'" fill="var(--teal)"/>';
    g+='<rect x="'+(L+wTP).toFixed(1)+'" y="'+y2+'" width="'+(pw-wTP).toFixed(1)+'" height="'+h+'" fill="var(--gold)"/>';
    if (wTP>44) g+='<text class="val" x="'+(L+4)+'" y="'+(y2+h/2+4)+'">'+(post*100).toFixed(1)+'%</text>';
    var lblTrue = al()==="en"?"true":(al()==="nl"?"echt":"vraies");
    var lblFalse = al()==="en"?"false":(al()==="nl"?"vals":"fausses");
    g+='<text class="ax" x="'+(L+2)+'" y="'+(y2+h+16)+'" fill="var(--teal)" text-anchor="start">'+lblTrue+'</text>';
    g+='<text class="ax" x="'+(L+pw-2)+'" y="'+(y2+h+16)+'" fill="var(--gold)" text-anchor="end">'+lblFalse+'</text>';
    svg.innerHTML=g;
  }
  ["by-prior","by-sens","by-fpr"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
